-- Internal reporting controls only; no spendable balance, provider or clinical mutation.
CREATE TABLE public.fin_reconciliation_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),partner_id uuid NOT NULL REFERENCES public.partners(id),location_id uuid REFERENCES public.locations(id),period_from timestamptz NOT NULL,period_to timestamptz NOT NULL,report jsonb NOT NULL,fingerprint text NOT NULL,actor uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(partner_id,location_id,period_from,period_to,fingerprint));
GRANT SELECT ON public.fin_reconciliation_snapshots TO authenticated;GRANT ALL ON public.fin_reconciliation_snapshots TO service_role;ALTER TABLE public.fin_reconciliation_snapshots ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.fin_adjustments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),partner_id uuid NOT NULL REFERENCES public.partners(id),location_id uuid REFERENCES public.locations(id),source text NOT NULL CHECK(source IN ('PARTNER','ANNUAL')),source_id uuid NOT NULL,quantity int NOT NULL CHECK(quantity<>0 AND abs(quantity)<=1000000),reason text NOT NULL,evidence_reference text NOT NULL,reversal_of uuid UNIQUE REFERENCES public.fin_adjustments(id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.fin_adjustments TO authenticated;GRANT ALL ON public.fin_adjustments TO service_role;ALTER TABLE public.fin_adjustments ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.fin_control_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),partner_id uuid NOT NULL,location_id uuid,adjustment_id uuid REFERENCES public.fin_adjustments(id),snapshot_id uuid REFERENCES public.fin_reconciliation_snapshots(id),action text NOT NULL CHECK(action IN ('proposed','verified','approved','rejected','closed','exception_acknowledged')),reason text NOT NULL,evidence_reference text NOT NULL,verification_method text,actor uuid NOT NULL,correlation_id uuid NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
GRANT SELECT ON public.fin_control_events TO authenticated;GRANT ALL ON public.fin_control_events TO service_role;ALTER TABLE public.fin_control_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.fin_compensating_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),adjustment_id uuid NOT NULL UNIQUE REFERENCES public.fin_adjustments(id),partner_id uuid NOT NULL,location_id uuid,source text NOT NULL CHECK(source IN ('PARTNER','ANNUAL')),source_id uuid NOT NULL,quantity int NOT NULL,actor uuid NOT NULL,approver uuid NOT NULL,correlation_id uuid NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
GRANT SELECT ON public.fin_compensating_entries TO authenticated;GRANT ALL ON public.fin_compensating_entries TO service_role;ALTER TABLE public.fin_compensating_entries ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.fin_control_operations(key uuid PRIMARY KEY,actor uuid NOT NULL,partner_id uuid NOT NULL,location_id uuid,intent jsonb NOT NULL,result jsonb NOT NULL);
GRANT ALL ON public.fin_control_operations TO service_role;ALTER TABLE public.fin_control_operations ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.fin_scope(_u uuid,_p uuid,_l uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _u IS NOT NULL AND _p IS NOT NULL AND EXISTS(SELECT 1 FROM partners WHERE id=_p) AND (_l IS NULL OR EXISTS(SELECT 1 FROM locations WHERE id=_l AND partner_id=_p)) AND EXISTS(SELECT 1 FROM user_roles WHERE user_id=_u AND status='ACTIVE' AND ((role='SUPER_ADMIN' AND partner_id IS NULL) OR (role='OPERATIONS_ADMIN' AND partner_id=_p))) $$;
CREATE POLICY fin_snapshot_read ON public.fin_reconciliation_snapshots FOR SELECT TO authenticated USING(fin_scope(auth.uid(),partner_id,location_id));
CREATE POLICY fin_adjustment_read ON public.fin_adjustments FOR SELECT TO authenticated USING(fin_scope(auth.uid(),partner_id,location_id));
CREATE POLICY fin_event_read ON public.fin_control_events FOR SELECT TO authenticated USING(fin_scope(auth.uid(),partner_id,location_id));
CREATE POLICY fin_entry_read ON public.fin_compensating_entries FOR SELECT TO authenticated USING(fin_scope(auth.uid(),partner_id,location_id));
CREATE TRIGGER fin_snapshot_immutable BEFORE UPDATE OR DELETE ON public.fin_reconciliation_snapshots FOR EACH ROW EXECUTE FUNCTION public.care_immutable();
CREATE TRIGGER fin_adjustment_immutable BEFORE UPDATE OR DELETE ON public.fin_adjustments FOR EACH ROW EXECUTE FUNCTION public.care_immutable();
CREATE TRIGGER fin_event_immutable BEFORE UPDATE OR DELETE ON public.fin_control_events FOR EACH ROW EXECUTE FUNCTION public.care_immutable();
CREATE TRIGGER fin_entry_immutable BEFORE UPDATE OR DELETE ON public.fin_compensating_entries FOR EACH ROW EXECUTE FUNCTION public.care_immutable();
CREATE TRIGGER fin_operation_immutable BEFORE UPDATE OR DELETE ON public.fin_control_operations FOR EACH ROW EXECUTE FUNCTION public.care_immutable();
-- Normalized unit movements: reservation reduces available, consume resolves reserved units
-- without a second deduction, releases after expiry do not revive expired eligibility.
CREATE FUNCTION public.fin_ledger(_p uuid) RETURNS TABLE(id text,source text,source_id uuid,location_id uuid,request_id uuid,correlation_id text,action text,quantity int,delta int,at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT 'grant:'||l.id,'PARTNER',l.id,NULL::uuid,NULL::uuid,NULL::text,'GRANT',l.granted,l.granted,l.purchased_at FROM care_credit_lots l WHERE l.partner_id=_p
UNION ALL SELECT t.id::text,'PARTNER',coalesce(h.lot_id,(t.metadata->>'lot_id')::uuid,(SELECT id FROM care_credit_lots WHERE payment_id=(t.metadata->>'payment_id')::uuid LIMIT 1)),c.care_location_id,r.id,t.idempotency_key,t.type::text,abs(t.quantity),CASE WHEN t.type='RESERVE' THEN -t.quantity WHEN t.type='CONSUME' THEN 0 WHEN t.type='RELEASE' THEN CASE WHEN l.expires_at>t.created_at THEN t.quantity ELSE 0 END WHEN t.type='ADJUSTMENT' THEN CASE WHEN l.expires_at<=t.created_at AND t.idempotency_key LIKE 'care:reverse:%' THEN 0 WHEN t.idempotency_key LIKE 'care:opening:%' OR t.idempotency_key LIKE 'care:legacy-close:%' THEN 0 ELSE t.quantity END ELSE 0 END,t.created_at FROM credit_transactions t LEFT JOIN consultations c ON c.id=t.consultation_id LEFT JOIN consultation_requests r ON r.consultation_id=c.id LEFT JOIN care_holds h ON h.consultation_id=c.id LEFT JOIN care_credit_lots l ON l.id=h.lot_id WHERE t.partner_id=_p
UNION ALL SELECT 'annual-grant:'||m.id,'ANNUAL',m.id,NULL,NULL,NULL,'GRANT',12,12,m.starts_at FROM memberships m WHERE m.care_sponsor_id=_p AND m.care_terms IS NOT NULL
UNION ALL SELECT a.id::text,'ANNUAL',m.id,c.care_location_id,r.id,coalesce((SELECT e.correlation_id::text FROM consultation_request_events e WHERE e.request_id=r.id ORDER BY e.created_at LIMIT 1),a.id::text),a.action,1,CASE a.action WHEN 'RESERVE' THEN -1 WHEN 'RELEASE' THEN CASE WHEN m.expires_at>a.created_at THEN 1 ELSE 0 END WHEN 'REVERSE' THEN CASE WHEN m.expires_at>a.created_at THEN 1 ELSE 0 END ELSE 0 END,a.created_at FROM care_annual_usage a JOIN memberships m ON m.id=a.membership_id LEFT JOIN consultations c ON c.id=a.consultation_id LEFT JOIN consultation_requests r ON r.consultation_id=c.id WHERE m.care_sponsor_id=_p
UNION ALL SELECT 'direct:'||h.id,'DIRECT',h.payment_id,c.care_location_id,r.id,h.id::text,'RESERVE',1,0,h.created_at FROM care_holds h JOIN consultations c ON c.id=h.consultation_id LEFT JOIN consultation_requests r ON r.consultation_id=c.id WHERE h.partner_id=_p AND c.care_kind='DIRECT'
UNION ALL SELECT 'direct-resolve:'||h.id,'DIRECT',h.payment_id,c.care_location_id,r.id,h.id::text,CASE h.state WHEN 'CONSUMED' THEN 'CONSUME' WHEN 'RELEASED' THEN 'RELEASE' ELSE h.state END,1,0,h.resolved_at FROM care_holds h JOIN consultations c ON c.id=h.consultation_id LEFT JOIN consultation_requests r ON r.consultation_id=c.id WHERE h.partner_id=_p AND c.care_kind='DIRECT' AND h.resolved_at IS NOT NULL
$$;
CREATE FUNCTION public.fin_movements(_p uuid) RETURNS TABLE(id text,source text,source_id uuid,location_id uuid,request_id uuid,correlation_id text,action text,quantity int,delta int,at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT * FROM fin_ledger(_p)
UNION ALL SELECT 'expire:'||l.id,'PARTNER',l.id,NULL,NULL,NULL,'EXPIRE',greatest(l.granted+coalesce((SELECT sum(e.delta) FROM fin_ledger(_p)e WHERE e.source_id=l.id AND e.source='PARTNER' AND e.action<>'GRANT' AND e.at<l.expires_at),0)::int,0),-greatest(l.granted+coalesce((SELECT sum(e.delta) FROM fin_ledger(_p)e WHERE e.source_id=l.id AND e.source='PARTNER' AND e.action<>'GRANT' AND e.at<l.expires_at),0)::int,0),l.expires_at FROM care_credit_lots l WHERE l.partner_id=_p
UNION ALL SELECT 'annual-expire:'||m.id,'ANNUAL',m.id,NULL,NULL,NULL,'EXPIRE',greatest(12+coalesce((SELECT sum(e.delta) FROM fin_ledger(_p)e WHERE e.source_id=m.id AND e.action<>'GRANT' AND e.at<m.expires_at),0)::int,0),-greatest(12+coalesce((SELECT sum(e.delta) FROM fin_ledger(_p)e WHERE e.source_id=m.id AND e.action<>'GRANT' AND e.at<m.expires_at),0)::int,0),m.expires_at FROM memberships m WHERE m.care_sponsor_id=_p AND m.care_terms IS NOT NULL
$$;
CREATE FUNCTION public.fin_anomalies(_p uuid,_l uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('category',category,'source',source,'reference',ref,'request_id',request_id) ORDER BY category,ref),'[]') FROM (
SELECT 'negative_balance' category,'PARTNER' source,_p::text ref,NULL::uuid request_id WHERE care_available(_p)<0
UNION ALL SELECT 'ledger_mismatch','PARTNER',l.id::text,NULL FROM care_credit_lots l WHERE l.partner_id=_p AND (l.used<>(SELECT count(*) FROM care_holds h WHERE h.lot_id=l.id AND h.state='CONSUMED') OR l.granted-l.used-l.voided<0)
UNION ALL SELECT 'ledger_mismatch','ANNUAL',m.id::text,NULL FROM memberships m WHERE m.care_sponsor_id=_p AND m.care_terms IS NOT NULL AND m.care_used<>(SELECT count(*) FROM care_holds h WHERE h.membership_id=m.id AND h.state='CONSUMED')
UNION ALL SELECT 'orphan_reservation',coalesce(c.care_kind,'PARTNER'),h.id::text,r.id FROM care_holds h LEFT JOIN consultations c ON c.id=h.consultation_id LEFT JOIN consultation_requests r ON r.consultation_id=c.id WHERE h.partner_id=_p AND (_l IS NULL OR c.care_location_id=_l) AND h.state='RESERVED' AND (c.id IS NULL OR (h.lot_id IS NULL AND h.membership_id IS NULL AND h.payment_id IS NULL) OR (h.lot_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM credit_transactions t WHERE t.consultation_id=h.consultation_id AND t.type='RESERVE')) OR (h.membership_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM care_annual_usage a WHERE a.consultation_id=h.consultation_id AND a.action='RESERVE')))
UNION ALL SELECT 'missing_release',c.care_kind,h.id::text,r.id FROM care_holds h JOIN consultations c ON c.id=h.consultation_id LEFT JOIN consultation_requests r ON r.consultation_id=c.id WHERE h.partner_id=_p AND (_l IS NULL OR c.care_location_id=_l) AND h.state='RESERVED' AND c.status IN ('CANCELLED','FAILED','NO_SHOW')
UNION ALL SELECT 'duplicate_consume','PARTNER',t.consultation_id::text,r.id FROM credit_transactions t LEFT JOIN consultation_requests r ON r.consultation_id=t.consultation_id WHERE t.partner_id=_p AND t.type='CONSUME' AND (_l IS NULL OR r.location_id=_l) GROUP BY t.consultation_id,r.id HAVING count(*)>1
UNION ALL SELECT 'duplicate_consume','ANNUAL',a.consultation_id::text,r.id FROM care_annual_usage a JOIN memberships m ON m.id=a.membership_id LEFT JOIN consultation_requests r ON r.consultation_id=a.consultation_id WHERE m.care_sponsor_id=_p AND a.action='CONSUME' AND (_l IS NULL OR r.location_id=_l) GROUP BY a.consultation_id,r.id HAVING count(*)>1
UNION ALL SELECT 'expired_entitlement_mismatch','ANNUAL',m.id::text,NULL FROM memberships m WHERE m.care_sponsor_id=_p AND m.care_terms IS NOT NULL AND (m.care_used<0 OR m.care_used>12 OR (m.status='ACTIVE' AND m.expires_at<=now() AND EXISTS(SELECT 1 FROM care_holds h WHERE h.membership_id=m.id AND h.created_at>=m.expires_at)))
) a $$;
CREATE FUNCTION public.fin_report(_p uuid,_l uuid,_from timestamptz,_to timestamptz) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE report jsonb;BEGIN IF NOT coalesce(fin_scope(auth.uid(),_p,_l),false) THEN RAISE EXCEPTION 'FINANCE_SCOPE_REQUIRED';END IF;IF _from IS NULL OR _to IS NULL OR _from>=_to OR _to>now() OR _to-_from>interval '366 days' THEN RAISE EXCEPTION 'INVALID_PERIOD';END IF;
SELECT jsonb_build_object('version',1,'partner_id',_p,'location_id',_l,'period_from',_from,'period_to',_to,'branch_allocation',CASE WHEN _l IS NULL THEN 'organization' ELSE 'activity_only_shared_pool' END,'posting_effect','internal_reporting_only','totals',(SELECT jsonb_agg(t ORDER BY source) FROM(SELECT s.source,coalesce(sum(e.delta) FILTER(WHERE e.at<_from),0) opening,coalesce(sum(e.quantity) FILTER(WHERE e.at>=_from AND e.action='GRANT'),0) grants,coalesce(sum(e.quantity) FILTER(WHERE e.at>=_from AND e.action='RESERVE'),0) reservations,coalesce(sum(e.quantity) FILTER(WHERE e.at>=_from AND e.action='RELEASE'),0) releases,coalesce(sum(e.quantity) FILTER(WHERE e.at>=_from AND e.action='CONSUME'),0) consumptions,coalesce(sum(e.quantity) FILTER(WHERE e.at>=_from AND e.action='EXPIRE'),0) expirations,coalesce(sum(e.delta) FILTER(WHERE e.at>=_from AND e.action='ADJUSTMENT'),0) lifecycle_adjustments,coalesce(sum(e.delta),0) closing,coalesce((SELECT sum(x.quantity) FROM fin_compensating_entries x WHERE x.partner_id=_p AND x.source=s.source AND (_l IS NULL OR x.location_id=_l) AND x.created_at>=_from AND x.created_at<_to),0) approved_reporting_adjustments FROM unnest(ARRAY['PARTNER','ANNUAL','DIRECT']) s(source) LEFT JOIN fin_movements(_p)e ON e.source=s.source AND e.at<_to AND (_l IS NULL OR e.location_id=_l) GROUP BY s.source)t),'entries',(SELECT coalesce(jsonb_agg(t ORDER BY at,id),'[]') FROM(SELECT * FROM fin_movements(_p) WHERE at>=_from AND at<_to AND (_l IS NULL OR location_id=_l) ORDER BY at,id LIMIT 500)t),'entry_count',(SELECT count(*) FROM fin_movements(_p) WHERE at>=_from AND at<_to AND (_l IS NULL OR location_id=_l)),'exceptions',fin_anomalies(_p,_l),'observed_available',CASE WHEN _l IS NULL THEN (SELECT coalesce(sum(delta),0) FROM fin_movements(_p) WHERE source='PARTNER' AND at<_to) ELSE NULL END,'adjustment_entries',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'source',source,'source_id',source_id,'quantity',quantity,'actor',actor,'approver',approver,'correlation_id',correlation_id,'created_at',created_at) ORDER BY created_at,id),'[]') FROM fin_compensating_entries WHERE partner_id=_p AND (_l IS NULL OR location_id=_l) AND created_at>=_from AND created_at<_to),'exception_basis','current_state_at_capture','complete_export',(SELECT count(*)<=500 FROM fin_movements(_p) WHERE at>=_from AND at<_to AND (_l IS NULL OR location_id=_l))) INTO report;RETURN report;END $$;
CREATE FUNCTION public.fin_adjustment_state(_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT action FROM fin_control_events WHERE adjustment_id=_id ORDER BY created_at DESC,id DESC LIMIT 1),'proposed') $$;
CREATE FUNCTION public.fin_console(_mode text,_p uuid DEFAULT NULL,_l uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid:=auth.uid();BEGIN IF u IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED';END IF;IF _mode='super' THEN IF NOT care_super(u) THEN RAISE EXCEPTION 'SUPER_REQUIRED';END IF;RETURN jsonb_build_object('snapshots',(SELECT count(*) FROM fin_reconciliation_snapshots),'adjustments',(SELECT count(*) FROM fin_adjustments),'pending',(SELECT count(*) FROM fin_adjustments WHERE fin_adjustment_state(id) IN ('proposed','verified')),'approved',(SELECT count(*) FROM fin_compensating_entries),'rows','[]'::jsonb);END IF;IF _mode<>'admin' OR NOT coalesce(fin_scope(u,_p,_l),false) THEN RAISE EXCEPTION 'FINANCE_SCOPE_REQUIRED';END IF;RETURN jsonb_build_object('snapshots',(SELECT coalesce(jsonb_agg(s),'[]') FROM(SELECT id,period_from,period_to,fingerprint,created_at,report,(SELECT action FROM fin_control_events WHERE snapshot_id=s.id AND action='closed' LIMIT 1) close_status FROM fin_reconciliation_snapshots s WHERE partner_id=_p AND location_id IS NOT DISTINCT FROM _l ORDER BY created_at DESC LIMIT 50)s),'adjustments',(SELECT coalesce(jsonb_agg(a),'[]') FROM(SELECT a.*,fin_adjustment_state(id) status FROM fin_adjustments a WHERE partner_id=_p AND (_l IS NULL OR location_id=_l) ORDER BY created_at DESC LIMIT 100)a),'events',(SELECT coalesce(jsonb_agg(e),'[]') FROM(SELECT action,adjustment_id,snapshot_id,actor,correlation_id,created_at FROM fin_control_events WHERE partner_id=_p AND (_l IS NULL OR location_id=_l) ORDER BY created_at DESC LIMIT 100)e),'entries',(SELECT coalesce(jsonb_agg(e),'[]') FROM(SELECT * FROM fin_compensating_entries WHERE partner_id=_p AND (_l IS NULL OR location_id=_l) ORDER BY created_at DESC LIMIT 100)e));END $$;
CREATE FUNCTION public.fin_command(_op text,_args jsonb,_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
#variable_conflict use_variable
DECLARE u uuid:=auth.uid();p uuid:=(_args->>'partner_id')::uuid;l uuid:=(_args->>'location_id')::uuid;i uuid:=(_args->>'id')::uuid;why text:=btrim(coalesce(_args->>'reason',''));evidence text:=btrim(coalesce(_args->>'evidence_reference',''));a fin_adjustments;s fin_reconciliation_snapshots;prior fin_control_operations;result jsonb;body jsonb;st text;verifier uuid;old fin_adjustments;delta int;sid uuid;src text; event uuid:=gen_random_uuid();
BEGIN IF u IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED';END IF;PERFORM care_require_strong();IF _key IS NULL OR _args IS NULL OR jsonb_typeof(_args)<>'object' OR length(_args::text)>2000 OR length(why) NOT BETWEEN 3 AND 500 OR evidence !~ '^[A-Za-z0-9][A-Za-z0-9_:/.-]{2,119}$' OR EXISTS(SELECT 1 FROM jsonb_object_keys(_args)k WHERE k<>ALL(ARRAY['partner_id','location_id','id','source','source_id','quantity','reason','evidence_reference','period_from','period_to','verification_method'])) THEN RAISE EXCEPTION 'INVALID_ARGUMENTS';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(_key::text,0));SELECT * INTO prior FROM fin_control_operations WHERE key=_key;IF FOUND THEN IF prior.actor<>u OR prior.intent<>jsonb_build_object('op',_op,'args',_args) THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';END IF;IF NOT fin_scope(u,prior.partner_id,prior.location_id) THEN RAISE EXCEPTION 'FINANCE_SCOPE_REQUIRED';END IF;RETURN prior.result;END IF;
IF _op IN ('verify','approve','reject','reverse') THEN SELECT * INTO a FROM fin_adjustments WHERE id=i FOR UPDATE;p:=a.partner_id;l:=a.location_id;ELSIF _op IN ('close','export','acknowledge') THEN SELECT * INTO s FROM fin_reconciliation_snapshots WHERE id=i FOR UPDATE;p:=s.partner_id;l:=s.location_id;END IF;IF NOT coalesce(fin_scope(u,p,l),false) THEN RAISE EXCEPTION 'FINANCE_SCOPE_REQUIRED';END IF;PERFORM 1 FROM partners WHERE id=p FOR UPDATE;
IF _op='snapshot' THEN body:=fin_report(p,l,(_args->>'period_from')::timestamptz,(_args->>'period_to')::timestamptz);SELECT id INTO i FROM fin_reconciliation_snapshots WHERE partner_id=p AND location_id IS NOT DISTINCT FROM l AND period_from=(_args->>'period_from')::timestamptz AND period_to=(_args->>'period_to')::timestamptz AND fingerprint=md5(body::text);IF i IS NULL THEN INSERT INTO fin_reconciliation_snapshots(partner_id,location_id,period_from,period_to,report,fingerprint,actor) VALUES(p,l,(_args->>'period_from')::timestamptz,(_args->>'period_to')::timestamptz,body,md5(body::text),u) RETURNING id INTO i;END IF;st:='proposed';
ELSIF _op IN ('propose','reverse') THEN IF _op='reverse' THEN IF fin_adjustment_state(a.id)<>'approved' OR EXISTS(SELECT 1 FROM fin_adjustments WHERE reversal_of=a.id) THEN RAISE EXCEPTION 'APPROVED_REVERSAL_REQUIRED';END IF;delta:=-a.quantity;sid:=a.source_id;src:=a.source;ELSE delta:=(_args->>'quantity')::int;sid:=(_args->>'source_id')::uuid;src:=_args->>'source';END IF;
IF src='PARTNER' THEN IF NOT EXISTS(SELECT 1 FROM care_credit_lots WHERE id=sid AND partner_id=p) OR l IS NOT NULL THEN RAISE EXCEPTION 'SHARED_POOL_OR_SOURCE_REQUIRED';END IF;ELSIF src='ANNUAL' THEN IF NOT EXISTS(SELECT 1 FROM memberships WHERE id=sid AND care_sponsor_id=p AND care_terms IS NOT NULL) OR l IS NOT NULL THEN RAISE EXCEPTION 'SHARED_POOL_OR_SOURCE_REQUIRED';END IF;ELSE RAISE EXCEPTION 'DIRECT_CANNOT_ADJUST';END IF;
INSERT INTO fin_adjustments(partner_id,location_id,source,source_id,quantity,reason,evidence_reference,reversal_of,created_by) VALUES(p,l,src,sid,delta,why,evidence,CASE WHEN _op='reverse' THEN a.id END,u) RETURNING id INTO i;st:='proposed';
ELSIF _op='verify' THEN IF fin_adjustment_state(i)<>'proposed' OR _args->>'verification_method' IS NULL OR _args->>'verification_method' NOT IN ('source_ledger_review','independent_evidence_review') THEN RAISE EXCEPTION 'VERIFICATION_REQUIRED';END IF;st:='verified';
ELSIF _op='approve' THEN SELECT actor INTO verifier FROM fin_control_events WHERE adjustment_id=i AND action='verified';IF fin_adjustment_state(i)<>'verified' OR a.created_by=u OR verifier=u THEN RAISE EXCEPTION 'INDEPENDENT_APPROVAL_REQUIRED';END IF;INSERT INTO fin_compensating_entries(adjustment_id,partner_id,location_id,source,source_id,quantity,actor,approver,correlation_id) VALUES(i,p,l,a.source,a.source_id,a.quantity,a.created_by,u,_key);st:='approved';
ELSIF _op='reject' THEN IF fin_adjustment_state(i) NOT IN ('proposed','verified') THEN RAISE EXCEPTION 'INVALID_STATE';END IF;st:='rejected';
ELSIF _op='close' THEN IF s.actor=u OR jsonb_array_length(s.report->'exceptions')<>0 OR EXISTS(SELECT 1 FROM fin_control_events WHERE snapshot_id=i AND action='closed') THEN RAISE EXCEPTION 'INDEPENDENT_CLEAR_CLOSE_REQUIRED';END IF;IF jsonb_array_length(fin_anomalies(p,l))<>0 OR EXISTS(SELECT 1 FROM fin_adjustments WHERE partner_id=p AND fin_adjustment_state(id) IN ('proposed','verified')) THEN RAISE EXCEPTION 'UNRESOLVED_EXCEPTIONS';END IF;IF md5(fin_report(p,l,s.period_from,s.period_to)::text)<>s.fingerprint THEN RAISE EXCEPTION 'STALE_SNAPSHOT';END IF;st:='closed';
ELSIF _op='acknowledge' THEN st:='exception_acknowledged';
ELSIF _op='export' THEN result:=jsonb_build_object('fingerprint',s.fingerprint,'report',s.report,'redacted',true,'external_delivery',false);st:=NULL;
ELSE RAISE EXCEPTION 'UNKNOWN_OPERATION';END IF;
IF st IS NOT NULL THEN INSERT INTO fin_control_events(id,partner_id,location_id,adjustment_id,snapshot_id,action,reason,evidence_reference,verification_method,actor,correlation_id) VALUES(event,p,l,CASE WHEN _op IN ('propose','reverse','verify','approve','reject') THEN i END,CASE WHEN _op IN ('snapshot','close','acknowledge') THEN i END,st,why,evidence,_args->>'verification_method',u,_key);PERFORM notification_enqueue('financial',i,event,'credit_anomaly',p,l,st,NULL,_key);IF _op='snapshot' AND jsonb_array_length(body->'exceptions')>0 THEN PERFORM notification_enqueue('financial',i,gen_random_uuid(),'credit_anomaly',p,l,'anomaly_detected',NULL,_key);END IF;END IF;
INSERT INTO audit_log(actor_user_id,partner_id,location_id,action,entity_type,entity_id,metadata) VALUES(u,p,l,'FIN_'||upper(_op),'financial_control',i::text,jsonb_build_object('correlation_id',_key,'state',st,'reporting_only',true));result:=coalesce(result,jsonb_build_object('id',i,'state',st,'spendable_balance_changed',false));INSERT INTO fin_control_operations VALUES(_key,u,p,l,jsonb_build_object('op',_op,'args',_args),result);RETURN result;END $$;
REVOKE ALL ON FUNCTION public.fin_scope(uuid,uuid,uuid),public.fin_ledger(uuid),public.fin_movements(uuid),public.fin_anomalies(uuid,uuid),public.fin_report(uuid,uuid,timestamptz,timestamptz),public.fin_adjustment_state(uuid),public.fin_console(text,uuid,uuid),public.fin_command(text,jsonb,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.fin_scope(uuid,uuid,uuid),public.fin_report(uuid,uuid,timestamptz,timestamptz),public.fin_console(text,uuid,uuid),public.fin_command(text,jsonb,uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.notification_source_access(_kind text,_id uuid,_p uuid,_l uuid,_u uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
BEGIN
IF _u IS NULL OR privacy_blocked(privacy_notification_patient(_kind,_id),'NOTIFICATION') THEN RETURN false;END IF;
IF _kind='financial' THEN RETURN fin_scope(_u,_p,_l) AND (EXISTS(SELECT 1 FROM fin_adjustments WHERE id=_id AND partner_id=_p AND location_id IS NOT DISTINCT FROM _l) OR EXISTS(SELECT 1 FROM fin_reconciliation_snapshots WHERE id=_id AND partner_id=_p AND location_id IS NOT DISTINCT FROM _l));END IF;
IF _kind='sla' THEN RETURN EXISTS(SELECT 1 FROM operational_sla_cases s WHERE s.id=_id AND s.partner_id=_p AND s.location_id IS NOT DISTINCT FROM _l AND sla_scope(_u,s.partner_id,s.location_id));END IF;
IF _kind='application' THEN RETURN partner_application_access(_id,_u);END IF;
IF _kind='request' THEN RETURN consultation_request_access(_id,_u);END IF;
IF _kind='certificate' THEN RETURN certificate_read(_id,_u);END IF;
IF _kind='handoff' THEN RETURN EXISTS(SELECT 1 FROM care_mcs_handoffs h WHERE h.id=_id AND (notification_admin(_u,h.partner_id) OR partner_customer_write(_u,h.partner_id,h.location_id)));END IF;
IF _kind IN ('doctor','assignment') THEN RETURN notification_admin(_u,_p) OR EXISTS(SELECT 1 FROM doctors d LEFT JOIN doctor_assignments a ON a.doctor_id=d.id WHERE d.auth_user_id=_u AND ((_kind='doctor' AND d.id=_id) OR (_kind='assignment' AND a.id=_id)) AND EXISTS(SELECT 1 FROM user_roles r WHERE r.user_id=_u AND r.role='DOCTOR' AND r.status='ACTIVE'));END IF;
RETURN notification_admin(_u,_p);END $$;